-- Class notes synopsis batch 22: Rose Hips through Schizandra

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Rose Hips</strong> (Rosa spp.) are <strong>cooling</strong>, <strong>sour</strong>, <strong>astringent</strong>, <strong>demulcent</strong>, and <strong>anti-inflammatory</strong> - one of the essential herbs of the Middle Ages in western Europe; very high in Vitamin C. For <strong>rheumatoid arthritis</strong>: antioxidant, buffers oxidative waste. "Pleasure medicine" - shifts mood for a few seconds; powerful clearer of <strong>lactic acid</strong> - good for gym-goers; use as strong decoction or tincture; dose: 1/2-6 droppers full (very safe); deseed before use; match anti-inflammatory action to constitution. Astringent and demulcent to the <strong>digestive system</strong> (similar to <a href="?herb=85"><strong>Plantain</strong></a>). For <strong>anemia</strong> and <strong>pregnancy support</strong>: source of Vitamin C to support iron metabolism; ingredient (1 tsp) in Iron Tonic Syrup for pregnancy alongside dried fruits. Heart decoction recipe (to 32 oz water): 28g <a href="?herb=73"><strong>Hawthorn</strong></a> berries, 28g Rose Hips, 14g <a href="?herb=167"><strong>Cinnamon</strong></a>. Rosehip oil: specific for holding skin pH (4.2-4.0) - use in oilination protocols to maintain acid mantle.$$
WHERE id = 849;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Rose</strong> (Rosa spp.) petals are a <strong>spirit remedy</strong> for <strong>depression</strong> - "resilience of the heart; self-love"; for <strong>stagnant depression</strong>, grief, heart loss, and emotional processing; for depression from loss, scattered depression, and lack of boundaries; "the most primal of the fragrances; cools an overheated liver; comforts the heart; resists infection; Rose Cordial strengthens the spirit of the heart." Rose flower essence (FE) for grief support. Paired with <a href="?herb=13"><strong>Tulsi</strong></a> as "atmospheric space." <strong>Astringent</strong> and <strong>tonifying</strong> - tannin-rich, drying, constricting; for <strong>chronic IBS</strong> and <strong>diarrhea</strong>; Upper GI astringent. For <strong>erectile dysfunction</strong>: aphrodisiac. Cooling - cools overheated <strong>liver</strong>; rose water for animals with skin issues; cooling of tempers. Topically for <strong>postpartum healing</strong>: tissue repair. Sitz bath for perineal healing: <a href="?herb=70"><strong>Calendula</strong></a>, <a href="?herb=54"><strong>Elecampane</strong></a>, Rose petals, <a href="?herb=44"><strong>Yarrow</strong></a>. Perineal wash: <a href="?herb=70"><strong>Calendula</strong></a>, <a href="?herb=85"><strong>Plantain</strong></a>, Rose, <a href="?herb=44"><strong>Yarrow</strong></a>. Daily Tea blend: 5p <a href="?herb=45"><strong>Marshmallow</strong></a> leaf, 4p <a href="?herb=61"><strong>Mullein</strong></a>, 3p <a href="?herb=90"><strong>Linden</strong></a>, 2p Rose, 1p <a href="?herb=167"><strong>Cinnamon</strong></a>. Thorns = protective, keep the heart open but maintain boundaries.$$
WHERE id = 850;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Rosemary</strong> (Salvia rosmarinus) is a <strong>warming</strong>, <strong>drying</strong>, <strong>nervine stimulant</strong>, <strong>circulatory stimulant</strong>, <strong>carminative</strong>, <strong>diaphoretic</strong>, <strong>antimicrobial</strong>, and <strong>neuroprotective</strong> herb with resins and monoterpenes; pungent - stimulates digestion, circulation, and metabolism; "Rosmarinus = dew of the sea"; grounding and resilient. Rosmarinic acid: supports <strong>methylation</strong>, estrogen metabolism in <strong>fibroids</strong>, and liver detoxification; in absorption tincture for <strong>thyroid/Hashimoto's</strong> alongside <a href="?herb=13"><strong>Tulsi</strong></a>, <a href="?herb=17"><strong>Schizandra</strong></a>, <a href="?herb=20"><strong>Ashwagandha</strong></a>, <a href="?herb=206"><strong>Milk Thistle</strong></a> to support nutrient absorption through methylation. For <strong>thyroid</strong>: rosmarinic acid calms thyroid response, slows uptake of T3 into tissues - more indicated for <strong>hyperthyroidism</strong> but no harm for hypo; modulates T-cells in autoimmune thyroid conditions - use with <a href="?herb=2437"><strong>Self Heal</strong></a> and <a href="?herb=134"><strong>Lemon Balm</strong></a>. For <strong>cognitive function</strong>: cerebral stimulant for <strong>brain fog</strong>, memory, and brain blood flow; enhances brain dopamine levels; flavonoid antioxidant for cognitive repair; for <strong>concussion</strong> alongside <a href="?herb=2632"><strong>Lion's Mane Mushroom</strong></a> and <a href="?herb=165"><strong>Ginkgo</strong></a>. For <strong>stagnant depression</strong>: warming, moving, lifts emotional stagnation - "for remembrance, the part that you lost"; good for brain fog and memory from depression; eases headaches; warming and stimulating. For <strong>digestion</strong>: specific for atonic digestive tract; carminative for <strong>hypochlorhydria</strong>; for <strong>headaches with indigestion</strong> (difficulty digesting proteins and fats). For <strong>respiratory</strong>: opens sinuses via volatile oils; used in steams for congestion; potential inhalation herb for <strong>bronchitis</strong> (volatile oil plant with scent). Circulatory stimulant especially for wet constitution; rosemary oil increases blood flow for <strong>arthritis</strong>. <strong>Antimicrobial</strong>: wound wash alongside culinary herbs, Four Thieves Vinegar, antimicrobial oxymel; can be used topically and internally. For <strong>hair</strong>: hair strength and growth; rosemary oil stimulates blood flow; vinegar rinse for dark hair; good anti-flea plant. Supports <strong>anxiety</strong> alongside <a href="?herb=78"><strong>Licorice</strong></a>. In Steady Study morning tea formula. Used in ceremonial burns. Resins not well extracted by water alone - consider preparation method. <strong>Not recommended due to anticoagulant properties - verify context before use.</strong>$$
WHERE id = 109;

