UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Sage</strong> (Salvia officinalis) is a <strong>warming</strong>, <strong>drying</strong>, <strong>antimicrobial</strong>, <strong>astringent</strong>, and <strong>carminative</strong> herb with aromatic volatile oils - sage-y smell indicates antimicrobial action; listed as one of the essential herbs of the Middle Ages in western Europe; key herb in African American herbal tradition. For <strong>infection</strong>: antimicrobial for <strong>sore throat</strong>, viral and bacterial infection; for <strong>common cold</strong>; in herbal steams for respiratory congestion; Four Thieves Vinegar; antimicrobial oxymel; smaller source of Vitamin A/Beta carotene; can be used topically and internally. For <strong>lactation suppression</strong>: suppresses prolactin levels - specific for drying up lactation after pregnancy loss; also used in <strong>PCOS</strong> picture for excess prolactin. For <strong>long COVID</strong>: part of Steven Buehner's protocol for stealth viral infections causing chronic pain. For <strong>digestion</strong>: carminative for <strong>hypochlorhydria</strong>; astringent for <strong>Hot Damp Diarrhea</strong>; inhibits H. pylori for <strong>peptic ulcer</strong>; Upper GI excess astringent alongside <a href="?herb=119"><strong>Bayberry</strong></a> and Rubus spp. Historical formulas: fussy colic baby - Sage with <a href="?herb=136"><strong>Catnip</strong></a>; immune support - Sage with <a href="?herb=89"><strong>Comfrey</strong></a> and <a href="?herb=84"><strong>Chamomile</strong></a> (cami weed); traditional African American glycerine syrup alongside <a href="?herb=84"><strong>Chamomile</strong></a>, <a href="?herb=89"><strong>Comfrey</strong></a>, and a flavonoid (<a href="?herb=134"><strong>Lemon Balm</strong></a> or mint). Hair: sage vinegar rinse for darkening grey hair.$$
WHERE id = 56;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Sarsaparilla</strong> (Smilax ornata) is a <strong>warming</strong>, <strong>alterative</strong>, <strong>liver alterative</strong>, <strong>lymphatic</strong>, and <strong>anticarcinogenic</strong> herb supporting all elimination pathways; GI alterative specifically indicated for <strong>leaky gut</strong> and <strong>food allergies</strong>. Clears excess <strong>estrogens</strong> alongside <a href="?herb=22"><strong>Burdock</strong></a>; clears excess androgens in the blood alongside <a href="?herb=22"><strong>Burdock</strong></a>, <a href="?herb=39"><strong>Figwort</strong></a>, and <a href="?herb=37"><strong>Yellow Dock</strong></a>. For <strong>perimenopause</strong>: metabolic support, supports all elimination pathways. For <strong>chemical sensitivity</strong>: in tea blend. For <strong>cancer care</strong>: anticarcinogenic, lymphatic support. Liver alterative for <strong>hot constitution</strong>; waste-eliminating alterative for <strong>wet constitution</strong>; warming for <strong>poor circulation</strong> and stagnation. For <strong>psoriasis</strong>: added to formula to buffer <a href="?herb=35"><strong>Poke Root</strong></a> and support liver. Combines well with <a href="?herb=186"><strong>Saw Palmetto</strong></a> for <strong>low testosterone</strong>.$$
WHERE id = 40;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Sassafras</strong> is an <strong>anti-inflammatory</strong>, <strong>anticarcinogenic</strong>, <strong>liver alterative</strong>, <strong>lymphatic</strong>, <strong>nervine</strong>, and <strong>circulatory</strong> herb from the African American/Black Herbal materia medica tradition - listed for cardiovascular and circulatory support; instructor notes the commonly cited safety studies were conducted incorrectly and on animals. Anti-inflammatory: alongside <a href="?herb=203"><strong>Turmeric</strong></a> - reduces LDL and decreases platelet aggregation (clots). <strong>Anticarcinogenic</strong>: inhibits, mitigates, prevents, and can help cure cancer; lymphatic herb for cancer support; Sassafras root in anti-cancer formula 2 (more intense, used in stages after formula 1). For <strong>chemo support</strong>: good taste, soothes nerves, reduces inflamed and hot tissue in tea. Liver alterative for <strong>hot constitution</strong>. Historical formula for <strong>chills, aches, and fever</strong>: Sassafras combined with <a href="?herb=320"><strong>Peach</strong></a> leaf and <a href="?herb=84"><strong>Chamomile</strong></a>.$$
WHERE id = 313;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Saw Palmetto</strong> (Serenoa repens) is a <strong>5-alpha-reductase inhibitor</strong>, <strong>anti-inflammatory</strong>, and <strong>androgen-modulating</strong> herb for <strong>men's health</strong>; strong taste, better in capsule form. For <strong>BPH</strong>: tonic and anti-inflammatory; Gaia Herbs formula - 2 caps/day preventative; herbal support alongside <a href="?herb=1649"><strong>Nettle Root</strong></a> and green tea. Down-regulates 5-alpha-reductase to reduce DHT in hormone-sensitive prostate tissue alongside <a href="?herb=1649"><strong>Nettle Root</strong></a>, green tea, <a href="?herb=203"><strong>Turmeric</strong></a>, <a href="?herb=11"><strong>Reishi Mushroom</strong></a>, and <a href="?herb=14"><strong>Ginseng</strong></a>. For <strong>prostate inflammation</strong> alongside <a href="?herb=1649"><strong>Nettle Root</strong></a>, <a href="?herb=296"><strong>Hydrangea</strong></a> root, and White sage. For <strong>excess androgens</strong>: anytime anyone has elevated androgens - certain balding patterns, elevated testosterone in PCOS/PMOS. For <strong>erectile dysfunction</strong>: hormone balancer. Combines well with <a href="?herb=40"><strong>Sarsaparilla</strong></a> for <strong>low testosterone</strong>.$$
WHERE id = 186;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Schizandra</strong> (Schisandra chinensis) is the <strong>five-flavor berry</strong> (sour, sweet, bitter + more) - what flavor you taste is said to be what you need; a <strong>sour</strong>, <strong>cooling</strong>, <strong>astringent</strong>, <strong>moistening adaptogen</strong>, <strong>hepatoprotective</strong>, <strong>lung tonic</strong>, and <strong>immune amphoteric</strong>; "Liver medicine, Anger medicine"; associated with longevity and beauty in TCM; "zing and confidence." Mildly stimulating adaptogen: non-toxic at high doses, non-specific, acts on H-P-A axis for stress resilience; "mind-pumping" - enhances focus, cognitive function, and clarity; helps regulate cortisol and balance energy; for <strong>ADHD</strong> and cognitive support; in Steady Study morning tea formula; personal adaptogen formula with <a href="?herb=81"><strong>St. John's Wort</strong></a> and <a href="?herb=14"><strong>Ginseng</strong></a>; in adaptogen/immune tonic protocol with <a href="?herb=225"><strong>Astragalus</strong></a> and <a href="?herb=11"><strong>Reishi Mushroom</strong></a>. Hepatic: liver protective and regenerative; restores liver after alcohol damage; supports Phase 1 liver detox as first line against toxins (alcohol and caffeine); reduces oxidative stress; associated with reducing cardiac insults of anger - cardioprotective; more gentle than other liver herbs; frequent in food sensitivity clinical settings; in hepatics/detox protocol alongside <a href="?herb=206"><strong>Milk Thistle</strong></a>, <a href="?herb=43"><strong>Nettle</strong></a>, <a href="?herb=42"><strong>Red Clover</strong></a>, <a href="?herb=28"><strong>Cleavers</strong></a>, <a href="?herb=37"><strong>Yellow Dock</strong></a>. For <strong>thyroid/Hashimoto's</strong>: moistening adaptogen when tissues are dry from hyperthyroid burnout; in main absorption tincture with <a href="?herb=13"><strong>Tulsi</strong></a>, <a href="?herb=20"><strong>Ashwagandha</strong></a>, <a href="?herb=206"><strong>Milk Thistle</strong></a>, <a href="?herb=109"><strong>Rosemary</strong></a>. For <strong>Kapha</strong>: sour and stimulating for congestion, edema, hypothyroid disorders, fatigue, stagnancy - sour flavor liquifies mucus. For <strong>lungs</strong>: specific ability to liquify hardened, accumulated lung material for deep <strong>chronic lung congestion</strong>; immune amphoteric for <strong>allergic asthma</strong>. Sour taste = moistening energetic quality - moistening adaptogen for dry constitution; berry as adaptogen for wet constitution also. Moves blood; hormone-balancing and astringent; for excess discharges and signs of laxness; in tincture for hormone and uterine support. For <strong>PCOS</strong>: "Temple of Devotion" formula for liver and energy. For <strong>infertility</strong>: reduces stress via adaptogenic action. Eat a couple berries in the morning; for liver deficiency conditions; linked to longevity.$$
WHERE id = 17;
